def parse_rows(block):
    return [[int(x) for x in line.split()] for line in block.strip().splitlines()]
def extract_input(text, marker):
    start=text.index(marker)+len(marker)
    end=text.find('\n\n', start)
    return parse_rows(text[start:end])
t0=records[5]['message']['content'][0]['text']
test=extract_input(t0,'Test input (24x24):\n')
examples=[]
for ix in (10,14):
    text=records[ix]['message']['content'][0]['text']
    inp=extract_input(text, 'input (24x24):\n')
    om=re.search(r'output \(\d+x\d+\):\n(.*?)(?:\n\nSame instance)',text,re.S)
    out=parse_rows(om.group(1))
    examples.append((inp,out))
print(len(test),len(test[0]), [(len(a),len(a[0]),len(b),len(b[0])) for a,b in examples])
